    static let viewBox: CGFloat = 24

    /// Path in a top-left-origin 24 box (draw in a flipped context).
    static func path(_ data: String) -> NSBezierPath {
        let path = NSBezierPath()
        var n: [CGFloat] = []
        var cmd = ""
        func flush() {
            switch (cmd, n.count) {
            case ("M", 2): path.move(to: NSPoint(x: n[0], y: n[1]))
            case ("L", 2): path.line(to: NSPoint(x: n[0], y: n[1]))
            case ("C", 6): path.curve(to: NSPoint(x: n[4], y: n[5]), controlPoint1: NSPoint(x: n[0], y: n[1]), controlPoint2: NSPoint(x: n[2], y: n[3]))
            case ("Z", _): path.close()
            default: break
            }
            n = []
        }
        for t in data.split(whereSeparator: \.isWhitespace) {
            if let v = Double(t) { n.append(CGFloat(v)) } else { flush(); cmd = String(t); if cmd == "Z" { flush(); cmd = "" } }
        }
        flush()
        return path
    }
